const fn = new Function(code + "\nreturn { classifyError };");
const { classifyError } = fn();
const e = new Error("fetch failed for /api");
e.name = "AbortError";
if (classifyError(e) !== "aborted") throw new Error("name === 'AbortError' must classify as aborted, even if the message mentions fetch.");
if (classifyError(new Error("Failed to fetch")) !== "network") throw new Error("A fetch/network message classifies as network.");

const fn = new Function(code + "\nreturn { classifyError };");
const { classifyError } = fn();
if (classifyError(null) !== "other") throw new Error("null must not crash — classify as other.");
if (classifyError("weird") !== "other") throw new Error("Non-Error values are other.");
if (classifyError(new Error("boom")) !== "other") throw new Error("Plain errors are other.");
